from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    row_cuts = [r for r, row in enumerate(grid) if len(set(row)) == 1 and row[0] != bg]
    col_cuts = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != bg]
    def spans(n, cuts):
        out, start = [], 0
        for cut in cuts:
            if start < cut:
                out.append((start, cut))
            start = cut + 1
        if start < n:
            out.append((start, n))
        return out
    rows, cols = spans(h, row_cuts), spans(w, col_cuts)
    panels = []
    for r0, r1 in rows:
        for c0, c1 in cols:
            panel = [row[c0:c1] for row in grid[r0:r1]]
            panels.append((sum(v != bg for row in panel for v in row), r0, r1, c0, c1, panel))
    _, _, _, _, _, pattern = max(panels, key=lambda x: x[0])
    ph, pw = len(pattern), len(pattern[0])
    out = [row[:] for row in grid]
    for _, r0, r1, c0, c1, _ in panels:
        if r1-r0 == ph and c1-c0 == pw:
            for i in range(ph):
                out[r0+i][c0:c1] = pattern[i][:]
    return out
